<script lang="ts">
 import Icon from './Icon.svelte';
 import type {PaperDraftController,PaperDraftState} from './lib/paper-draft';
 import type {PaperPort,PaperMetadata,SessionInfo,LegacyRun} from './lib/papers';
 import {renderMarkdown} from './lib/render';
 let {controller,state:info,port,context=null,destination='',reading=false,disabled=false,desktop=true,onExit}:{controller:PaperDraftController;state:PaperDraftState;port:Pick<PaperPort,'list'>&Partial<PaperPort>;context?:SessionInfo|null;destination?:string;reading?:boolean;disabled?:boolean;desktop?:boolean;onExit:()=>void}=$props();
 let moreOpen=$state(false);let attachedId='';
 $effect(()=>{const id=info.paper?.id??'';if(attachedId&&!id&&reading)moreOpen=false;attachedId=id;});
 let sourcePages=$state<string[]>([]),sourceNotice=$state(''),inspectedId='';
 let recent=$state<PaperMetadata[]>([]),oldPapers=$state<PaperMetadata[]>([]),legacy=$state<LegacyRun[]>([]),legacyText=$state(''),libraryNotice=$state('');
 const active=$derived(info.enabled||reading||!!context);
 async function inspectSource(){const id=info.paper?.id??context?.source.id;if(!id||!port.source)return;inspectedId=id;sourcePages=[];sourceNotice='正在读取本机提取原文…';try{const pages=await port.source(id);if((info.paper?.id??context?.source.id)===id){sourcePages=pages;sourceNotice='';}}catch(e){if(inspectedId===id)sourceNotice=String(e);}}
 async function library(){try{await controller.prepare();recent=await port.list();if(port.legacyPapers)oldPapers=await port.legacyPapers();if(port.legacy)legacy=await port.legacy();}catch(e){libraryNotice=String(e);}}
</script>
<div class="paper-feature" data-paper-feature>
 <div class="feature-row"><button class:enabled={active} class="paper-toggle" data-paper-toggle aria-pressed={active} disabled={disabled||!desktop} onclick={()=>{if(active)onExit();else void controller.enable();}}><Icon name="book" size={16}/>论文阅读</button>{#if active}<span>内置阅读重点与报告结构</span>{/if}</div>
 {#if active}
  <div class="paper-mini" data-paper-mini>
   <div class="paper-mini-head"><Icon name="book" size={18}/><div><strong>{info.paper?.name??context?.source.name??(reading?'论文阅读会话':'添加一篇 PDF')}</strong><small>{info.paper?`${info.paper.pageCount} 页 · 可提取 ${info.paper.readablePages}/${info.paper.pageCount} 页 · 点击发送开始分析`:context?`可提取 ${context.source.readablePages}/${context.source.pageCount} 页 · 围绕原文继续提问`:reading?'围绕原文继续提问':'默认全文精读，无需填写阅读要求'}</small></div><button class="paper-close" aria-label={info.paper?'移除论文附件':'关闭论文阅读'} title={info.paper?'移除附件':reading?'结束论文会话，准备普通新对话':'关闭论文阅读'} disabled={disabled} onclick={()=>{if(info.paper)controller.remove();else onExit();}}>×</button></div>
   {#if !info.paper&&!context&&!reading}<div class="paper-mini-actions"><button data-paper-upload disabled={disabled||info.importing||info.restoring} onclick={()=>void controller.choose()}>{info.importing?'正在导入…':'上传 PDF'}</button></div>{/if}
   <details data-paper-more bind:open={moreOpen}><summary>阅读选项与资料</summary>
   <div class="paper-mini-actions">{#if info.paper||context||reading}<button data-paper-upload disabled={disabled||info.importing||info.restoring} onclick={()=>void controller.choose()}>{info.importing?'正在导入…':info.paper||context?'更换 PDF':'上传 PDF'}</button>{/if}<details class="paper-library" ontoggle={e=>{if(e.currentTarget.open)void library();}}><summary>已导入论文</summary><div class="paper-library-items">{#each recent as p}<button disabled={disabled||!info.loaded} onclick={()=>controller.attach(p)}>{p.name} · {p.pageCount} 页</button>{/each}{#if !recent.length}<small>还没有已导入论文</small>{/if}{#if oldPapers.length||legacy.length}<details><summary>旧版资料（只读）</summary>{#each oldPapers as p}<button onclick={()=>void port.legacyOpen?.(p.id).catch(e=>libraryNotice=String(e))}>打开原件：{p.name}</button>{/each}{#each legacy as r}<button onclick={()=>void port.legacyReport?.(r.runId).then(text=>legacyText=text).catch(e=>libraryNotice=String(e))}>{r.name} · {r.state}</button>{/each}{#if legacyText}<div class="prose">{@html renderMarkdown(legacyText)}</div>{/if}</details>{/if}{#if libraryNotice}<p role="alert">{libraryNotice}</p>{/if}</div></details></div>
   {#if info.paper&&info.loaded}
    <details data-paper-options><summary>阅读要求（已内置，可选修改）</summary>
     <div class="paper-option-row"><label>模式<select value={info.options.mode} disabled={disabled} onchange={e=>controller.edit({mode:e.currentTarget.value as typeof info.options.mode})}><option value="deep">标准精读</option><option value="quick">速读</option><option value="reproduce">复现准备</option><option value="interactive">交互学习</option></select></label><label>起始页<input type="number" min="1" max={info.paper.pageCount} value={info.options.startPage} disabled={disabled} oninput={e=>controller.edit({startPage:e.currentTarget.valueAsNumber})}/></label><label>结束页<input type="number" min={info.options.startPage} max={info.paper.pageCount} value={info.options.endPage} disabled={disabled} oninput={e=>controller.edit({endPage:e.currentTarget.valueAsNumber})}/></label></div>
     <label>关注问题<textarea rows="4" maxlength="8192" data-reading-focus value={info.options.focus} disabled={disabled} oninput={e=>controller.edit({focus:e.currentTarget.value})}></textarea></label>
     <label>输出要求<textarea rows="5" maxlength="8192" data-reading-output value={info.options.outputRequirements} disabled={disabled} oninput={e=>controller.edit({outputRequirements:e.currentTarget.value})}></textarea></label>
     <label>研究背景（可选）<textarea rows="2" maxlength="8192" data-reading-background value={info.options.background} disabled={disabled} oninput={e=>controller.edit({background:e.currentTarget.value})}></textarea></label>
     <button disabled={disabled} onclick={()=>controller.reset()}>恢复内置要求</button>
    </details>
   {:else if context}<details data-paper-saved-options><summary>查看当前会话的阅读范围与要求</summary><p>PDF物理页 {context.options.startPage}–{context.options.endPage||context.source.pageCount} · {context.endpoint} · {context.model}</p><p>{context.options.focus||'使用内置关注问题'}</p><p>{context.options.outputRequirements||'使用内置输出结构'}</p>{#if context.options.background}<p>研究背景：{context.options.background}</p>{/if}</details>{/if}
   {#if info.paper||context}<details ontoggle={e=>{if(e.currentTarget.open)void inspectSource();}}><summary>核对原文与缺页</summary>{#if sourceNotice}<p role="status">{sourceNotice}</p>{/if}{#each sourcePages as page,i}<details><summary>PDF物理页 {i+1}{page.trim()?'':' · 无可提取文字'}</summary><pre>{page||'本页没有可提取文字，扫描或图像内容未读取。'}</pre></details>{/each}</details>{/if}
   <small class="paper-privacy">导入保存在本机，发送时才提交所选原文和阅读要求。当前读取文字，图表图像需核对；草稿截图不随论文发送。</small>
   </details>
   <small data-paper-destination>{info.paper||!context?destination:context.endpoint+' · '+context.model}</small>
   {#if info.restoring}<p role="status">正在恢复论文附件…</p>{/if}
   {#if info.notice}<p role="status">{info.notice}</p>{/if}
  </div>
 {/if}
</div>
<style>
 .paper-feature{padding:10px 14px 0;flex-shrink:0}.feature-row{display:flex;align-items:center;gap:10px}.feature-row>span{font-size:12px;color:var(--muted)}button,select,input,textarea{font:inherit;color:var(--text);background:var(--surface);border:1px solid var(--edge);border-radius:10px}button{cursor:pointer;padding:6px 10px;font-size:13px}button:disabled{opacity:.5;cursor:default}.paper-toggle{display:inline-flex;align-items:center;gap:6px;background:var(--surface-soft);border-radius:20px}.paper-toggle.enabled{color:var(--accent);border-color:var(--accent)}.paper-mini{margin-top:10px;padding:12px 14px;border:1px solid var(--edge);border-radius:14px;background:var(--surface-soft);max-height:340px;overflow:auto}.paper-mini-head{display:flex;align-items:center;gap:9px}.paper-mini-head>div{flex:1;min-width:0;display:grid;gap:3px}.paper-mini strong{font-size:14px;overflow-wrap:anywhere}.paper-mini small{color:var(--muted);font-size:12px;line-height:1.6}.paper-close{border:0;background:transparent;font-size:20px;line-height:1;padding:4px 7px}.paper-mini-actions,.paper-option-row{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-top:9px}.paper-mini summary{cursor:pointer;font-size:12px;color:var(--muted);padding:5px 0}.paper-mini details>label{display:grid;gap:5px;margin:9px 0;font-size:13px}.paper-mini textarea{width:100%;box-sizing:border-box;padding:8px;font-size:13px;min-height:unset}.paper-option-row label{display:grid;gap:5px;font-size:12px}.paper-option-row input{width:70px;padding:5px}.paper-option-row select{padding:5px}.paper-privacy{display:block;margin-top:8px}.paper-library-items{display:grid;gap:6px;padding:6px 0;max-height:200px;overflow:auto}.paper-mini pre{white-space:pre-wrap;max-height:180px;overflow:auto;font:inherit;font-size:12px}.paper-mini p{font-size:12px;line-height:1.6;white-space:pre-wrap;overflow-wrap:anywhere;margin:8px 0}.paper-mini button:focus-visible,.paper-mini summary:focus-visible,.paper-toggle:focus-visible{outline:2px solid var(--focus-ring);outline-offset:2px}
</style>
